package fr.jmproduction.pocketdoor.recipe; import fr.jmproduction.pocketdoor.Content; import net.minecraft.world.item.*; import java.util.*;
public final class ResonanceRecipes { public record Entry(Item input, ItemStack output, int ticks){} private static final List<Entry> ALL=new ArrayList<>(); static{register(Content.RAW_TERTARIUM,Content.PURIFIED_TERTARIUM_CRYSTAL,200);register(Items.RAW_IRON,Items.IRON_INGOT,160);register(Items.RAW_GOLD,Items.GOLD_INGOT,180);register(Items.RAW_COPPER,Items.COPPER_INGOT,140);} public static void register(Item in,Item out,int ticks){ALL.add(new Entry(in,new ItemStack(out),ticks));} public static Entry find(ItemStack s){for(Entry e:ALL)if(e.input()==s.getItem())return e;return null;} private ResonanceRecipes(){} }
